// Step 1b: Validate Webhook Secret & Idempotency (Prevent Duplicate Double-Clicks)
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;

const expectedSecret = $env.BOOKLEAF_WEBHOOK_SECRET || 'bookleaf-secret-2026';
const providedSecret = headers['x-bookleaf-secret'] || headers['X-Bookleaf-Secret'] || body.webhook_secret || '';

if (providedSecret !== expectedSecret) {
  return [
    {
      json: {
        authorized: false,
        duplicate: false,
        error_code: 'UNAUTHORIZED_WEBHOOK',
        error_message: 'Invalid or missing x-bookleaf-secret authentication header.',
        author_id: body.author_id || 'UNKNOWN',
        notification_log_id: body.notification_log_id || null,
        bubble_api_base_url: body.bubble_api_base_url || '',
        bubble_api_token: body.bubble_api_token || ''
      }
    }
  ];
}

// Idempotency check using workflow staticData (60-second deduplication window per author_id)
const staticData = $getWorkflowStaticData('global');
if (!staticData.recentTriggers) {
  staticData.recentTriggers = {};
}

const now = Date.now();
const authorId = (body.author_id || '').trim();
const forceBypass = Boolean(body.force_retrigger);
const lastTriggeredAt = staticData.recentTriggers[authorId] || 0;
const IDEMPOTENCY_WINDOW_MS = 60 * 1000; // 60 seconds

// Clean up expired keys
for (const [k, ts] of Object.entries(staticData.recentTriggers)) {
  if (now - ts > IDEMPOTENCY_WINDOW_MS) {
    delete staticData.recentTriggers[k];
  }
}

if (authorId && !forceBypass && now - lastTriggeredAt < IDEMPOTENCY_WINDOW_MS) {
  return [
    {
      json: {
        authorized: true,
        duplicate: true,
        error_code: 'DUPLICATE_REQUEST_IGNORED',
        error_message: `Idempotency lock active: Royalty summary for ${authorId} was already triggered ${Math.round((now - lastTriggeredAt) / 1000)}s ago.`,
        author_id: authorId,
        notification_log_id: body.notification_log_id || null,
        bubble_api_base_url: body.bubble_api_base_url || '',
        bubble_api_token: body.bubble_api_token || ''
      }
    }
  ];
}

if (authorId) {
  staticData.recentTriggers[authorId] = now;
}

return [
  {
    json: {
      authorized: true,
      duplicate: false,
      author_id: authorId,
      author_name: body.author_name || null,
      author_email: body.author_email || null,
      author_city: body.author_city || null,
      books_payload: body.books || null,
      notification_log_id: body.notification_log_id || null,
      bubble_api_base_url: body.bubble_api_base_url || $env.BUBBLE_API_BASE_URL || '',
      bubble_api_token: body.bubble_api_token || $env.BUBBLE_API_TOKEN || '',
      send_real_email: Boolean(body.send_real_email ?? true),
      triggered_by: body.triggered_by || 'Admin Portal',
      request_timestamp: new Date(now).toISOString()
    }
  }
];

